/**
 * Conversions between the three units the page geometry has to speak.
 *
 * The writer drags margins in **rem**, because that is what the editor's
 * type scale is built on and what every stored `LayoutSettings` holds. The
 * sheet they print on is measured in **inches**, because paper is physical.
 * Layout happens in **CSS pixels**. Everything crosses between the three
 * here rather than in a dozen call sites, so a change to the bridge is a
 * change in one place.
 *
 * `CSS_PX_PER_IN` is fixed by the CSS spec at 96, and it is the same number
 * Chrome's print engine uses when laying out `@page`. That is what makes
 * screen and print agree — but only when the root font size is what we
 * think it is, which is why the export pins `html { font-size: 16px }`
 * while the screen deliberately does not (see `resolvePageSetup`).
 */
import { CSS_PX_PER_IN } from "../types";

/** The browser default, and the value every export is pinned to. */
export const DEFAULT_ROOT_FONT_PX = 16;

/**
 * Current root font size in CSS pixels.
 *
 * On the server, or if the computed value is nonsense, fall back to the
 * browser default rather than propagating a NaN into every page height.
 */
export function rootFontSize(): number {
  if (typeof window === "undefined" || typeof document === "undefined") {
    return DEFAULT_ROOT_FONT_PX;
  }
  const size = parseFloat(
    getComputedStyle(document.documentElement).fontSize || "16",
  );
  return Number.isFinite(size) && size > 0 ? size : DEFAULT_ROOT_FONT_PX;
}

/** rem → CSS px, against an explicit root size so callers stay testable. */
export function remToPx(rem: number, rootPx: number = DEFAULT_ROOT_FONT_PX) {
  return rem * rootPx;
}

/** CSS px → rem. */
export function pxToRem(px: number, rootPx: number = DEFAULT_ROOT_FONT_PX) {
  return px / rootPx;
}

/** CSS px → inches. Spec-fixed, no root font size involved. */
export function pxToIn(px: number): number {
  return px / CSS_PX_PER_IN;
}

/** Inches → CSS px. */
export function inToPx(inches: number): number {
  return inches * CSS_PX_PER_IN;
}

/** Inches → millimetres, for the ruler's readout. */
export function inToMm(inches: number): number {
  return inches * 25.4;
}

/**
 * Format a rem margin for display in the writer's chosen unit.
 *
 * Used by the ruler readout, which shows both the stored value and the
 * physical one so "3 rem" and "half an inch" stop being different languages.
 */
export function formatMargin(
  rem: number,
  unit: "rem" | "in" | "mm",
  rootPx: number = DEFAULT_ROOT_FONT_PX,
): string {
  if (unit === "rem") return `${rem.toFixed(2)} rem`;
  const inches = pxToIn(remToPx(rem, rootPx));
  if (unit === "in") return `${inches.toFixed(2)} in`;
  return `${inToMm(inches).toFixed(1)} mm`;
}

import { describe, expect, test } from "bun:test";
import {
  DEFAULT_LAYOUT,
  PAPER_SIZE_IN,
  resolvePageSetup,
  type LayoutSettings,
} from "../types";
import {
  formatMargin,
  inToPx,
  pxToIn,
  pxToRem,
  remToPx,
} from "./css-units";

/**
 * Page setup arrived after pagination did, which means every folio written
 * before it exists without a single one of these fields. The contract that
 * matters most here is the boring one: an old document must still open onto
 * the page its writer expected, not onto a blank default.
 */
describe("resolvePageSetup", () => {
  const legacy: LayoutSettings = {
    width: "normal",
    margin: "normal",
    runningHeader: false,
    pageNumbers: true,
  };

  test("a document written before pagination resolves to Letter portrait", () => {
    const s = resolvePageSetup(legacy);
    expect(s.paper).toBe("letter");
    expect(s.orientation).toBe("portrait");
    expect(s.pagination).toBe("paginated");
    expect(s.marginUnit).toBe("rem");
    expect(s.widthIn).toBe(8.5);
    expect(s.heightIn).toBe(11);
  });

  test("landscape swaps the sheet dimensions", () => {
    const s = resolvePageSetup({ ...legacy, orientation: "landscape" });
    expect(s.widthIn).toBe(11);
    expect(s.heightIn).toBe(8.5);
  });

  test("A4 is 210 x 297 mm", () => {
    // The stored inches are the source of truth; check they round-trip to
    // the millimetre figures the rest of the world uses for A4.
    const s = resolvePageSetup({ ...legacy, paper: "a4" });
    expect(s.widthIn * 25.4).toBeCloseTo(210, 1);
    expect(s.heightIn * 25.4).toBeCloseTo(297, 1);
  });

  test("legal is letter-width but taller", () => {
    const s = resolvePageSetup({ ...legacy, paper: "legal" });
    expect(s.widthIn).toBe(PAPER_SIZE_IN.letter.w);
    expect(s.heightIn).toBe(14);
  });

  test("continuous mode is honoured rather than overridden", () => {
    const s = resolvePageSetup({ ...legacy, pagination: "continuous" });
    expect(s.pagination).toBe("continuous");
  });

  test("an unrecognised paper falls back to Letter instead of NaN", () => {
    // Defensive: a hand-edited or future-versioned folio must not produce a
    // page of undefined height, which would divide the whole engine by zero.
    const s = resolvePageSetup({
      ...legacy,
      paper: "tabloid" as LayoutSettings["paper"],
    });
    expect(s.widthIn).toBe(8.5);
    expect(s.heightIn).toBe(11);
  });

  test("the default layout resolves to its own declared values", () => {
    const s = resolvePageSetup(DEFAULT_LAYOUT);
    expect(s.paper).toBe("letter");
    expect(s.orientation).toBe("portrait");
    expect(s.pagination).toBe("paginated");
  });
});

/**
 * The unit bridge. If these drift, screen and print drift with them.
 */
describe("css-units", () => {
  test("rem and px agree at a 16px root", () => {
    expect(remToPx(3)).toBe(48);
    expect(pxToRem(48)).toBe(3);
  });

  test("px and inches agree at the spec-fixed 96/in", () => {
    expect(pxToIn(48)).toBe(0.5);
    expect(inToPx(8.5)).toBe(816);
  });

  test("a non-default root font size scales rem but not inches", () => {
    // This is the one knowing divergence between screen and print: the
    // reader's text scaling moves the margins, while the sheet stays 8.5in.
    expect(remToPx(3, 20)).toBe(60);
    expect(inToPx(8.5)).toBe(816);
  });

  test("formatMargin speaks all three units", () => {
    expect(formatMargin(3, "rem")).toBe("3.00 rem");
    expect(formatMargin(3, "in")).toBe("0.50 in");
    expect(formatMargin(3, "mm")).toBe("12.7 mm");
  });
});

/**
 * The pagination engine, with the DOM taken out of it.
 *
 * Everything here is arithmetic over plain numbers: measured block heights in,
 * page break positions and spacer heights out. Nothing in this file touches a
 * document, a view, or a stylesheet — which is the point. Pagination is the
 * one part of the editor where an off-by-a-few-pixels bug is invisible until
 * it isn't, so the part that can be wrong is the part that can be unit tested,
 * exactly as `popover-positioning.ts` did for the mark popovers.
 *
 * ## The invariant
 *
 * Spacers are sized so that every page's content top lands on a uniform grid:
 *
 *     renderedTop(page k) = k * (pageH + gap)
 *
 * measured from the top of page 0's content area. That single property is what
 * makes the rest of the feature cheap: the sheet edges can be painted with one
 * `repeating-linear-gradient` instead of N DOM nodes, and the running header
 * and page number for page k sit at a position you can compute with a multiply
 * rather than by asking the browser.
 *
 * ## Why the measure/decorate loop cannot oscillate
 *
 * The naive engine reads each block's `offsetTop`, inserts spacers, and finds
 * that every `offsetTop` has changed — so it measures again, forever. We never
 * read `offsetTop`. The caller reports only `height`, `marginTop` and
 * `marginBottom` per block, and {@link buildNaturalStack} reconstructs the
 * un-paginated stack from those. Because a spacer changes neither a block's
 * width nor its height, the inputs to this function are invariant under its
 * own output. The fixed point is structural, not a tuning parameter.
 *
 * This matters concretely: headings carry `margin-top: 2.2rem` which collapses
 * with the preceding paragraph's `margin-bottom`, and a spacer inserted between
 * them would stop that collapse. An engine reading `offsetTop` would shift by
 * ~15px at every heading break and never settle. One that computes the stack
 * is immune, because it models the collapse itself.
 */
import {
  DOC_WIDTH_REM,
  resolveMargins,
  resolvePageSetup,
  type LayoutSettings,
} from "../../types";
import { DEFAULT_ROOT_FONT_PX, inToPx, remToPx } from "../../utils/css-units";

/** Visual gap between two sheets, in rem. */
export const PAGE_GAP_REM = 1.5;

/**
 * A single top-level block, as measured in the rendered document.
 *
 * Heights are CSS pixels and come from `offsetHeight` (border box); margins
 * come from `getComputedStyle`. Never derive these from character counts or
 * an assumed column width — `indent.ts` narrows blocks by up to 16rem, and
 * only the rendered height knows what that did to the line wrapping.
 */
export interface BlockMetric {
  /** ProseMirror document position of the block's start. */
  pos: number;
  /** Rendered border-box height, CSS px. */
  height: number;
  /** Computed `margin-top`, CSS px. */
  marginTop: number;
  /** Computed `margin-bottom`, CSS px. */
  marginBottom: number;
  /**
   * This block is a `pageBreak` node. It forces a break before itself and
   * contributes no height of its own — the visible rule and label are drawn
   * by the page chrome overlay, in the gap, so a manual break never leaves a
   * stray line hanging at the top of the following page.
   */
  forcedBreak?: boolean;
  /**
   * This block must never be the last on a page — headings, in practice.
   * Mirrors `break-after: avoid` in the print stylesheet so screen and paper
   * make the same decision.
   */
  keepWithNext?: boolean;
}

/** The page, in CSS pixels. All derived from `LayoutSettings` + paper size. */
export interface PageGeometry {
  /** Full sheet height. */
  pageH: number;
  /** Full sheet width. */
  pageW: number;
  /** Gap painted between two sheets. */
  gap: number;
  /** Top page margin. */
  marginTop: number;
  /** Bottom page margin. */
  marginBottom: number;
  /** Left page margin. */
  marginLeft: number;
  /** Right page margin. */
  marginRight: number;
  /** `pageH - marginTop - marginBottom`; the usable height on one sheet. */
  contentH: number;
  /** `pageW - marginLeft - marginRight`; the text column width. */
  contentW: number;
}

export interface PageBreak {
  /** Index into the metrics array of the block that begins the new page. */
  blockIndex: number;
  /** ProseMirror position to hang the spacer widget on. */
  pos: number;
  /** Spacer height, CSS px. Always positive. */
  height: number;
  /** True when a `pageBreak` node caused this, rather than overflow. */
  forced: boolean;
  /** 0-based index of the page this break starts. */
  page: number;
}

export interface PaginationResult {
  breaks: PageBreak[];
  /** Total sheets, including any the tail element spills onto. */
  pageCount: number;
}

export interface PaginateOptions {
  /**
   * Height of content rendered after the editor but inside the page canvas —
   * the manuscript notes block. It is not a ProseMirror block, so the engine
   * cannot measure it as one, but it still has to fit on a sheet.
   */
  tailHeight?: number;
  /**
   * Hard ceiling on sheets. Past this the caller should fall back to a
   * continuous column rather than paint a thousand page frames.
   */
  maxPages?: number;
