59	   * Who is speaking, by name. The editor's inline cards read their author out
60	   * of a DOM attribute and have no persona object to hand, so the voice
61	   * fields above are filled in from the cast when only a name is known.
62	   */
63	  author?: string;
64	  /** Convex client for the hosted (Pro) path. BYOK does not need it. */
65	  client?: ConvexClient | null;
66	  /**
67	   * Is there an account behind `client`? The hosted path is sign-in *and*
68	   * Pro gated, so calling it while signed out only ever yields "Not signed
69	   * in" — a useless thing to show a writer who is reading aloud on their own
70	   * key and never asked for the hosted path at all.
71	   */
72	  signedIn?: boolean;
73	}
