75	export type SpeechStatus = "idle" | "loading" | "playing" | "error";
76	
77	export interface SpeechState {
78	  status: SpeechStatus;
79	  /** Which `SpeakRequest.id` is active, when any. */
80	  id: string | null;
81	  error: AppError | null;
82	}
83	
84	const state: SpeechState = { status: "idle", id: null, error: null };
85	
86	let audio: HTMLAudioElement | null = null;
87	/** Content-addressed clip cache: `${voice}::${text}` → object URL. */
88	const cache = new Map<string, string>();
89	/** Guards against a slow request landing after the writer moved on. */
90	let generation = 0;
91	
92	export function speechState(): SpeechState {
93	  return { ...state };
94	}
95	
96	function notify(): void {
97	  if (typeof window === "undefined") return;
98	  window.dispatchEvent(
99	    new CustomEvent("twyne:speech", { detail: speechState() }),
100	  );
101	}
102	
103	function setState(
104	  status: SpeechStatus,
105	  id: string | null,
106	  error: AppError | null = null,
107	): void {
108	  state.status = status;
109	  state.id = id;
110	  state.error = error;
111	  notify();
112	}
