114	function cacheKey(
115	  text: string,
116	  providerId: string,
117	  model: string,
118	  voice: string,
119	  responseFormat: string,
120	  speed: number | undefined,
121	  instructions: string | undefined,
122	): string {
123	  return [
124	    providerId,
125	    model,
126	    voice,
127	    responseFormat,
128	    speed ?? "",
129	    instructions ?? "",
130	    text,
131	  ].join("::");
132	}
133	
134	function remember(key: string, url: string): void {
135	  cache.set(key, url);
136	  while (cache.size > MAX_CACHED_CLIPS) {
137	    const oldest = cache.keys().next().value;
138	    if (oldest === undefined) break;
139	    const stale = cache.get(oldest);
140	    if (stale) URL.revokeObjectURL(stale);
141	    cache.delete(oldest);
142	  }
143	}
