145	/**
146	 * Pick the voice name for whichever provider will actually serve this request.
147	 * Falls back to the generic name when the provider has no specific entry, and
148	 * to nothing at all when there is no provider — in which case the synthesis
149	 * call is about to fail anyway.
150	 */
151	export function pickVoiceForProvider(
152	  voices: Partial<Record<AiProviderType, string>> | undefined,
153	  fallback: string | undefined,
154	  providerType: AiProviderType | undefined,
155	): string | undefined {
156	  if (providerType && voices?.[providerType]) return voices[providerType];
157	  return fallback;
158	}
159	
160	function resolveVoice(req: SpeakRequest, settings: AiSettings): string | undefined {
161	  return pickVoiceForProvider(
162	    req.voices,
163	    req.voice,
164	    resolveFeatureConfig(settings, "voice-narration")?.provider.type,
165	  );
166	}
167	
168	/**
169	 * Fill in the voice fields from the cast when the caller knows only a name.
170	 *
171	 * Read fresh rather than memoised: the writer can rename or revoice an editor
172	 * mid-session, and one IndexedDB read is nothing beside the synthesis call it
173	 * precedes.
174	 */
175	async function withPersonaVoice(req: SpeakRequest): Promise<SpeakRequest> {
176	  if (!req.author) return req;
177	  if (req.voice && req.voices && req.instructions) return req;
178	
179	  const name = req.author.trim().toLowerCase();
180	  if (!name) return req;
181	
182	  let cast: Persona[] = PERSONAS;
183	  try {
184	    const custom = await loadPersonasFromIdb();
185	    if (custom && custom.length > 0) cast = custom;
186	  } catch {
187	    // The defaults still carry voices; a failed read is not worth a silence.
188	  }
189	
190	  const persona = cast.find((p) => p.name.trim().toLowerCase() === name);
191	  if (!persona) return req;
192	
193	  return {
194	    ...req,
195	    voice: req.voice ?? persona.speechVoice,
196	    voices: req.voices ?? persona.speechVoices,
197	    instructions: req.instructions ?? persona.voice,
198	  };
199	}
200	
201	/**
202	 * A one-sample silent WAV. Playing this costs nothing audible and is the
203	 * cheapest way to spend a user gesture on the shared audio element.
204	 */
205	const SILENCE =
206	  "data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEARKwAAIhYAQACABAAZGF0YQAAAAA=";
207	
208	/**
209	 * Claim playback permission for the shared audio element.
210	 *
211	 * Autoplay policy grants `play()` only while a user gesture is still "fresh"
212	 * — about five seconds in Chrome. Synthesising a paragraph routinely takes
213	 * longer than that, so by the time the clip came back the gesture had expired
214	 * and `play()` rejected with NotAllowedError. Every press failed, which is
215	 * indistinguishable from the feature being broken.
216	 *
217	 * Once an element has played from within a gesture it stays unlocked for the
218	 * life of the page, so this runs synchronously on the press — before any
219	 * await — and never needs to run again.
220	 */
221	let unlocked = false;
222	export function unlockSpeechPlayback(): void {
223	  if (unlocked || typeof window === "undefined") return;
224	  audio = audio ?? new Audio();
225	  audio.muted = true;
226	  audio.src = SILENCE;
227	  const started = audio.play();
228	  if (started && typeof started.then === "function") {
229	    void started
230	      .then(() => {
231	        unlocked = true;
232	      })
233	      .catch(() => {
234	        // Still locked. The play() below will report it properly.
235	      })
236	      .finally(() => {
237	        if (audio) audio.muted = false;
238	      });
239	  } else {
240	    unlocked = true;
241	    audio.muted = false;
242	  }
243	}
244	
245	/** Stop whatever is playing. Safe to call when nothing is. */
246	export function stopSpeech(): void {
247	  generation += 1;
248	  if (audio) {
249	    audio.pause();
250	    audio.currentTime = 0;
251	  }
252	  setState("idle", null);
253	}
254	
255	type Synthesis = {
256	  audio: Blob;
257	  provider: string;
258	  model: string;
259	  voice: string;
260	};
261	
262	/**
263	 * Get generated audio for a passage.
264	 *
265	 * A configured BYOK voice provider is authoritative: its selected provider
266	 * and model are used, and failures are surfaced rather than silently changing
267	 * models. Hosted speech is considered only when no BYOK voice provider exists.
268	 */
269	async function synthesize(req: SpeakRequest): Promise<Synthesis> {
270	  const text = req.text.trim();
271	  const settings = await getCachedAiSettings();
272	
273	  // Gate on a provider that can *narrate*, not merely one that can do some
274	  // voice feature. `hasConfiguredVoiceProvider` is true for transcription-only
275	  // providers too (Google, say), and gating on it stranded any writer running
276	  // Anthropic for the room and Google for dictation: narration resolved to
277	  // nothing, this threw, and the hosted path below was never reached.
278	  const narrator = resolveFeatureConfig(settings, "voice-narration");
279	  if (narrator) {
280	    const result = await runClientVoiceSpeech(
281	      { text, voice: resolveVoice(req, settings), instructions: req.instructions },
282	      settings,
283	    );
284	    if (result) {
285	      return {
286	        audio: result.audio,
287	        provider: result.provider,
288	        model: result.model,
289	        voice: result.voice,
290	      };
291	    }
292	    throw createAppError("PROVIDER_ERROR", {
293	      source: "provider",
294	      metadata: {
295	        feature: "voice-narration",
296	        operation: "synthesize",
297	        provider: narrator.provider.type,
298	        model: narrator.model,
299	      },
300	    });
301	  }
302	
303	  if (req.client && req.signedIn) {
304	    try {
305	      const res = (await req.client.action(api.voice.synthesizeSpeech, {
306	        text,
307	        voice: req.voice,
308	        instructions: req.instructions,
309	      })) as { audioBase64: string; mimeType: string };
310	      const bytes = Uint8Array.from(atob(res.audioBase64), (c) =>
311	        c.charCodeAt(0),
312	      );
313	      return {
314	        audio: new Blob([bytes], { type: res.mimeType }),
315	        provider: "hosted",
316	        model: "hosted",
317	        voice: req.voice ?? "alloy",
318	      };
319	    } catch (err) {
320	      reportApplicationDiagnostic("twyne:speech:hosted-declined", err, {
321	        feature: "voice-narration",
322	      });
323	      throw err;
324	    }
325	  }
326	
327	  throw createAppError("CONFIGURATION_ERROR", {
328	    source: "application",
329	    recovery: { action: "choose-provider", canRetry: false },
330	    metadata: { feature: "voice-narration", operation: "synthesize" },
331	  });
332	}
333	
334	/**
335	 * Read a passage aloud. Pressing the same passage again stops it (so one
336	 * button is both play and stop); pressing a different one switches over.
337	 */
338	export async function speak(req: SpeakRequest): Promise<void> {
339	  if (typeof window === "undefined") return;
340	
341	  // Same passage, already sounding → this press means "stop".
342	  if (state.id === req.id && (state.status === "playing" || state.status === "loading")) {
343	    stopSpeech();
344	    return;
345	  }
346	
347	  const text = req.text.trim();
348	  if (!text) return;
349	
350	  // Still synchronous, so the press counts as a user gesture. Everything below
351	  // this line is too late to claim playback permission.
352	  unlockSpeechPlayback();
353	
354	  stopSpeech();
355	  const mine = ++generation;
356	  const spoken = await withPersonaVoice(req);
357	  // Key the cache on the voice that will actually be used, so two editors
358	  // sharing a fallback name never collide on one clip.
359	  const settings = await getCachedAiSettings();
360	  const resolved = resolveFeatureConfig(settings, "voice-narration");
361	  const override = settings.perFeature["voice-narration"];
362	  const voice = resolveVoice(spoken, settings) ?? spoken.voice ?? "alloy";
363	  const provider = resolved?.provider.id ?? "hosted";
364	  const model = resolved?.model ?? "hosted";
365	  const key = cacheKey(
366	    text,
367	    provider,
368	    model,
369	    voice,
370	    override?.responseFormat ?? "mp3",
371	    override?.speed,
372	    spoken.instructions ?? override?.instructions,
373	  );
374	
375	  setState("loading", req.id);
376	
377	  try {
378	    let url = cache.get(key);
379	    if (!url) {
380	      const result = await synthesize({ ...spoken, text });
381	      if (mine !== generation) return; // the writer moved on
382	      url = URL.createObjectURL(result.audio);
383	      remember(key, url);
384	    }
385	    if (mine !== generation) return;
386	
387	    audio = audio ?? new Audio();
388	    audio.muted = false;
389	    audio.src = url;
390	    audio.onended = () => {
391	      if (mine === generation) setState("idle", null);
392	    };
393	    audio.onerror = () => {
394	      if (mine !== generation) return;
395	      setState(
396	        "error",
397	        req.id,
398	        createAppError("PROVIDER_ERROR", {
399	          source: "provider",
400	          metadata: { feature: "voice-narration", operation: "playback" },
401	        }),
402	      );
403	    };
404	    await audio.play();
405	    if (mine === generation) setState("playing", req.id);
406	  } catch (err) {
407	    if (mine !== generation) return;
408	    // A blocked play() is not a provider failure, and telling the writer to
409	    // check their API key when the browser simply refused to make noise sends
410	    // them off to fix something that was never wrong.
411	    if (err instanceof DOMException && err.name === "NotAllowedError") {
412	      setState(
413	        "error",
414	        req.id,
415	        {
416	          ...createAppError("PERMISSION_DENIED", {
417	            source: "application",
418	            recovery: { action: "retry", canRetry: true },
419	            metadata: { feature: "voice-narration", operation: "playback" },
420	          }),
421	          message:
422	            "Your browser blocked playback. Press read aloud again to allow it.",
423	        },
424	      );
425	      return;
426	    }
427	    setState(
428	      "error",
429	      req.id,
430	      normalizeApplicationError(err, {
431	        source: "provider",
432	        metadata: { feature: "voice-narration", operation: "synthesize" },
433	      }),
434	    );
435	  }
436	}
437	
438	/** Drop every cached clip and release its object URL. */
439	export function clearSpeechCache(): void {
440	  for (const url of cache.values()) URL.revokeObjectURL(url);
441	  cache.clear();
442	}
