input.content:
/**
 * The editorial palette, in one place.
 *
 * Two lists, because the two jobs have opposite requirements. **Ink** colours
 * are saturated: they are the text itself, and they need to carry against
 * paper. **Highlight** colours are pale tints of the same hues: they sit
 * *behind* text that must stay readable, and a saturated highlighter turns a
 * sentence into a smear. Word and Docs make the same split for the same reason.
 *
 * Every swatch carries both a `cssVar` and a `hex`, and which one a caller
 * uses is not a matter of taste:
 *
 *   - **The editor writes `hex` into marks.** A mark styled
 *     `background-color: var(--color-mustard)` renders correctly in the app
 *     and renders *nothing* in an exported standalone HTML file, which has no
 *     such custom property defined. Colour that survives leaving the app has
 *     to be a literal.
 *   - **Chrome uses `cssVar`**, so a future theme can move it.
 *
 * Server-side rasterisers (`og-image.ts`) can only ever use `hex`; they run in
 * Node with no stylesheet at all.
 */

export interface Swatch {
  /** Stable identifier, safe to persist. */
  id: string;
  /** Human label, used for the accessible name. */
  label: string;
  /** Literal colour. What gets written into a document. */
  hex: string;
  /** Theme reference. What gets used for app chrome. */
  cssVar: string;
}

/**
 * Saturated inks — text colour, persona identity, annotation accents.
 *
 * The list this replaced had six entries but only four distinct colours:
 * "wine" pointed at `--color-persona-editor`, which is mustard, and "indigo"
 * at `--color-accent-blue`, which is cobalt. Two of the six swatches were
 * silently the same paint as two others.
 */
export const INK_SWATCHES: readonly Swatch[] = [
  { id: "vermilion", label: "Vermilion", hex: "#c1272d", cssVar: "var(--color-vermilion)" },
  { id: "mustard", label: "Mustard", hex: "#d4a017", cssVar: "var(--color-mustard)" },
  { id: "cobalt", label: "Cobalt", hex: "#2c4a7c", cssVar: "var(--color-cobalt)" },
  { id: "forest", label: "Forest", hex: "#5b7a3a", cssVar: "var(--color-accent-green)" },
  { id: "periwinkle", label: "Periwinkle", hex: "#5c6bc0", cssVar: "var(--color-periwinkle)" },
  { id: "sage", label: "Sage", hex: "#8a9a5b", cssVar: "var(--color-sage)" },
  { id: "blush", label: "Blush", hex: "#e8a598", cssVar: "var(--color-blush)" },
  { id: "ink", label: "Ink", hex: "#1f1b16", cssVar: "var(--color-ink)" },
];

/**
 * Pale tints for highlighting, one per ink hue so the two palettes read as
 * the same family. Each is light enough that the manuscript's ink (#1f1b16)
 * still clears WCAG AA on top of it — see `palette.test.ts`, which checks the
 * contrast rather than trusting the eye.
 */
export const HIGHLIGHT_SWATCHES: readonly Swatch[] = [
  { id: "butter", label: "Butter", hex: "#fbeaa8", cssVar: "var(--color-highlight-butter)" },
  { id: "rose", label: "Rose", hex: "#f8d3d4", cssVar: "var(--color-highlight-rose)" },
  { id: "sky", label: "Sky", hex: "#cfe0f2", cssVar: "var(--color-highlight-sky)" },
  { id: "mint", label: "Mint", hex: "#d5e6c4", cssVar: "var(--color-highlight-mint)" },
  { id: "lilac", label: "Lilac", hex: "#dcdff4", cssVar: "var(--color-highlight-lilac)" },
  { id: "peach", label: "Peach", hex: "#fadfd5", cssVar: "var(--color-highlight-peach)" },
];

/** The manuscript's body ink, for contrast checks against a highlight. */
export const MANUSCRIPT_INK = "#1f1b16";

export type PaletteKind = "ink" | "highlight";

export function swatchesFor(kind: PaletteKind): readonly Swatch[] {
  return kind === "highlight" ? HIGHLIGHT_SWATCHES : INK_SWATCHES;
}

/** Look a swatch up by the literal colour stored in a document. */
export function swatchByHex(
  hex: string,
  kind: PaletteKind,
): Swatch | undefined {
  const want = hex.trim().toLowerCase();
  return swatchesFor(kind).find((s) => s.hex.toLowerCase() === want);
}

/* ── Contrast, so a colour choice cannot quietly break readability ── */

export function parseHex(hex: string): { r: number; g: number; b: number } | null {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) return null;
  let body = m[1];
  if (body.length === 3) {
    body = body
      .split("")
      .map((c) => c + c)
      .join("");
  }
  return {
    r: parseInt(body.slice(0, 2), 16),
    g: parseInt(body.slice(2, 4), 16),
    b: parseInt(body.slice(4, 6), 16),
  };
}

/** Relative luminance, per WCAG 2.x. */
export function relativeLuminance(hex: string): number {
  const rgb = parseHex(hex);
  if (!rgb) return 0;
  const channel = (v: number) => {
    const s = v / 255;
    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
  };
  return (
    0.2126 * channel(rgb.r) + 0.7152 * channel(rgb.g) + 0.0722 * channel(rgb.b)
  );
}

/** WCAG contrast ratio between two colours, 1 to 21. */
export function contrastRatio(a: string, b: string): number {
  const la = relativeLuminance(a);
  const lb = relativeLuminance(b);
  const [hi, lo] = la > lb ? [la, lb] : [lb, la];
  return (hi + 0.05) / (lo + 0.05);
}

/**
 * Pick black or white for text sitting on an arbitrary background.
 *
 * Needed because the picker accepts any colour the writer likes, including
 * one dark enough that the manuscript's own ink disappears into it.
 */
export function readableInkOn(background: string): string {
  return contrastRatio(background, MANUSCRIPT_INK) >= 4.5
    ? MANUSCRIPT_INK
    : "#ffffff";
}

/** Normalise anything the colour input might hand back to `#rrggbb`. */
export function normalizeHex(value: string): string | null {
  const rgb = parseHex(value);
  if (!rgb) return null;
  const hex = (n: number) => n.toString(16).padStart(2, "0");
  return `#${hex(rgb.r)}${hex(rgb.g)}${hex(rgb.b)}`;
}

import { describe, expect, test } from "bun:test";
import {
  contrastRatio,
  HIGHLIGHT_SWATCHES,
  INK_SWATCHES,
  MANUSCRIPT_INK,
  normalizeHex,
  parseHex,
  readableInkOn,
  swatchByHex,
  swatchesFor,
} from "./palette";

describe("the palette is actually a palette", () => {
  test("no two ink swatches are the same paint", () => {
    // The list this replaced had six entries and four colours: "wine" was
    // mustard and "indigo" was cobalt. A picker that offers the same colour
    // twice under different names is worse than one with fewer choices.
    const hexes = INK_SWATCHES.map((s) => s.hex.toLowerCase());
    expect(new Set(hexes).size).toBe(hexes.length);
  });

  test("no two highlight swatches are the same paint", () => {
    const hexes = HIGHLIGHT_SWATCHES.map((s) => s.hex.toLowerCase());
    expect(new Set(hexes).size).toBe(hexes.length);
  });

  test("ids are unique and stable-looking", () => {
    for (const list of [INK_SWATCHES, HIGHLIGHT_SWATCHES]) {
      const ids = list.map((s) => s.id);
      expect(new Set(ids).size).toBe(ids.length);
      for (const id of ids) expect(id).toMatch(/^[a-z][a-z0-9-]*$/);
    }
  });

  test("every swatch carries a literal colour, not only a variable", () => {
    // A mark styled with var(--color-mustard) renders nothing in an exported
    // standalone HTML file. Colour that leaves the app has to be a literal.
    for (const s of [...INK_SWATCHES, ...HIGHLIGHT_SWATCHES]) {
      expect(s.hex).toMatch(/^#[0-9a-f]{6}$/i);
      expect(s.cssVar).toMatch(/^var\(--/);
    }
  });
});

describe("highlights stay readable", () => {
  test("manuscript ink clears WCAG AA on every highlight", () => {
    // The whole point of a highlight is that you can still read the sentence.
    for (const s of HIGHLIGHT_SWATCHES) {
      const ratio = contrastRatio(s.hex, MANUSCRIPT_INK);
      expect(ratio).toBeGreaterThanOrEqual(4.5);
    }
  });

  test("ink swatches are dark enough to read on paper", () => {
    const paper = "#f4ecd8";
    // Blush is a deliberate soft accent and is not offered as body colour;
    // everything else has to carry against the page.
    for (const s of INK_SWATCHES.filter((x) => x.id !== "blush")) {
      expect(contrastRatio(s.hex, paper)).toBeGreaterThanOrEqual(3);
    }
  });
});

describe("contrast maths", () => {
  test("black on white is the maximum ratio", () => {
    expect(contrastRatio("#000000", "#ffffff")).toBeCloseTo(21, 1);
  });

  test("a colour against itself is 1", () => {
    expect(contrastRatio("#c1272d", "#c1272d")).toBeCloseTo(1, 5);
  });

  test("readableInkOn flips to white only when ink would vanish", () => {
    expect(readableInkOn("#fbeaa8")).toBe(MANUSCRIPT_INK);
    expect(readableInkOn("#1a1a1a")).toBe("#ffffff");
  });
});

describe("hex handling", () => {
  test("shorthand expands", () => {
    expect(parseHex("#abc")).toEqual({ r: 0xaa, g: 0xbb, b: 0xcc });
  });

  test("a leading hash is optional", () => {
    expect(parseHex("c1272d")).toEqual({ r: 0xc1, g: 0x27, b: 0x2d });
  });

  test("nonsense is rejected rather than coerced", () => {
    expect(parseHex("rebeccapurple")).toBeNull();
    expect(parseHex("#12345")).toBeNull();
    expect(normalizeHex("not a colour")).toBeNull();
  });

  test("normalizeHex produces the canonical form", () => {
    expect(normalizeHex("#ABC")).toBe("#aabbcc");
    expect(normalizeHex("C1272D")).toBe("#c1272d");
  });
});

describe("lookup", () => {
  test("a stored colour resolves back to its swatch", () => {
    expect(swatchByHex("#C1272D", "ink")?.id).toBe("vermilion");
    expect(swatchByHex("#fbeaa8", "highlight")?.id).toBe("butter");
  });

  test("a custom colour resolves to nothing rather than the nearest swatch", () => {
    // The picker allows arbitrary colours; pretending one of them is
    // "vermilion" would mislabel it everywhere it is shown.
    expect(swatchByHex("#123456", "ink")).toBeUndefined();
  });

  test("the two palettes are kept separate", () => {
    expect(swatchesFor("ink")).toBe(INK_SWATCHES);
    expect(swatchesFor("highlight")).toBe(HIGHLIGHT_SWATCHES);
    expect(swatchByHex("#c1272d", "highlight")).toBeUndefined();
  });
});

