/**
 * The choices the formatting controls offer.
 *
 * Kept out of the editor component because they are data, not markup, and
 * because the export path needs the same font stacks — a manuscript set in
 * Special Elite has to print in Special Elite.
 */

export interface FontChoice {
  id: string;
  label: string;
  /** Full CSS stack. Written into the document, so it must stand alone. */
  stack: string;
}

/**
 * Only the families the app actually loads, plus the three generics.
 *
 * `root.tsx` pulls Fraunces, Lora, DM Sans and Special Elite from Google
 * Fonts. Offering anything else would be a lie: the writer would pick it, see
 * it locally because their machine happens to have it, and their reader would
 * get a fallback. A font menu is a promise about what the document will look
 * like somewhere else.
 */
export const FONT_CHOICES: readonly FontChoice[] = [
  { id: "serif", label: "Lora (serif)", stack: "var(--font-serif), Georgia, serif" },
  {
    id: "display",
    label: "Fraunces (display)",
    stack: "var(--font-display), Georgia, serif",
  },
  { id: "sans", label: "DM Sans", stack: "var(--font-sans), system-ui, sans-serif" },
  {
    id: "typewriter",
    label: "Special Elite",
    stack: "var(--font-typewriter), Courier, monospace",
  },
  { id: "mono", label: "Monospace", stack: "var(--font-mono), ui-monospace, monospace" },
];

/**
 * Point sizes, in the sequence a word processor offers. Stored as `rem` so a
 * document keeps its proportions under the reader's text scaling; the label is
 * the familiar point number.
 */
export const FONT_SIZES: readonly { label: string; value: string }[] = [
  { label: "9", value: "0.5625rem" },
  { label: "10", value: "0.625rem" },
  { label: "11", value: "0.6875rem" },
  { label: "12", value: "0.75rem" },
  { label: "14", value: "0.875rem" },
  { label: "16", value: "1rem" },
  { label: "18", value: "1.125rem" },
  { label: "24", value: "1.5rem" },
  { label: "30", value: "1.875rem" },
  { label: "36", value: "2.25rem" },
  { label: "48", value: "3rem" },
];

/** The line-spacing presets Word and Docs both settled on. */
export const LINE_SPACINGS: readonly { label: string; value: string }[] = [
  { label: "Single", value: "1.4" },
  { label: "1.15", value: "1.6" },
  { label: "1.5", value: "2.1" },
  { label: "Double", value: "2.8" },
];

/**
 * Space above and below a paragraph, in rem.
 *
 * Note these are *multiples of the editor's own 1.8 line-height baseline*
 * rather than raw CSS line-height values — the manuscript sets 1.8 by default,
 * so "single" has to mean 1.8-ish rather than 1.0, or choosing "single"
 * would visibly tighten a document nobody asked to change.
 */
export const PARAGRAPH_SPACINGS: readonly { label: string; value: number }[] = [
  { label: "None", value: 0 },
  { label: "Small", value: 0.5 },
  { label: "Medium", value: 1 },
  { label: "Large", value: 1.75 },
];

/** Title Case that leaves the small words alone, the way a copy desk would. */
const MINOR_WORDS = new Set([
  "a", "an", "and", "as", "at", "but", "by", "for", "from", "in", "into",
  "nor", "of", "on", "onto", "or", "over", "per", "the", "to", "up", "via",
  "with",
]);

export type TextCase = "upper" | "lower" | "title" | "sentence";

/**
 * Recase a run of text.
 *
 * Title case keeps minor words lowercase unless they open or close the string,
 * which is the rule every style guide agrees on and the one a naive
 * capitalise-every-word implementation gets wrong.
 */
export function recase(text: string, mode: TextCase): string {
  if (mode === "upper") return text.toUpperCase();
  if (mode === "lower") return text.toLowerCase();

  if (mode === "sentence") {
    const lower = text.toLowerCase();
    return lower.replace(/(^\s*\p{L})|([.!?]\s+\p{L})/gu, (m) =>
      m.toUpperCase(),
    );
  }

  // Title case. Split on whitespace but keep it, so the original spacing
  // survives — a writer selecting a line with a double space did not ask for
  // it to be tidied.
  const parts = text.split(/(\s+)/);
  const wordIndexes = parts
    .map((p, i) => (/\S/.test(p) ? i : -1))
    .filter((i) => i >= 0);
  const first = wordIndexes[0];
  const last = wordIndexes[wordIndexes.length - 1];

  return parts
    .map((part, i) => {
      if (!/\S/.test(part)) return part;
      const lower = part.toLowerCase();
      const bare = lower.replace(/[^\p{L}\p{N}]/gu, "");
      if (i !== first && i !== last && MINOR_WORDS.has(bare)) return lower;
      return lower.replace(/\p{L}/u, (c) => c.toUpperCase());
    })
    .join("");
}

import { describe, expect, test } from "bun:test";
import {
  FONT_CHOICES,
  FONT_SIZES,
  LINE_SPACINGS,
  recase,
} from "./typography-options";

describe("font choices", () => {
  test("every family the menu offers is one the app actually loads", () => {
    // A font menu is a promise about what the document will look like on
    // someone else's machine. Offering a family root.tsx never loads means the
    // writer sees it locally and their reader gets a fallback.
    const loaded = [
      "--font-serif",
      "--font-display",
      "--font-sans",
      "--font-typewriter",
      "--font-mono",
    ];
    for (const f of FONT_CHOICES) {
      expect(loaded.some((v) => f.stack.includes(v))).toBe(true);
    }
  });

  test("every stack carries a fallback", () => {
    // A custom property alone resolves to nothing in an exported document.
    for (const f of FONT_CHOICES) {
      expect(f.stack.split(",").length).toBeGreaterThan(1);
    }
  });

  test("ids are unique", () => {
    const ids = FONT_CHOICES.map((f) => f.id);
    expect(new Set(ids).size).toBe(ids.length);
  });
});

describe("sizes and spacings", () => {
  test("font sizes ascend", () => {
    const values = FONT_SIZES.map((s) => parseFloat(s.value));
    expect(values).toEqual([...values].sort((a, b) => a - b));
  });

  test("sizes are stored in rem so the reader's scaling still works", () => {
    for (const s of FONT_SIZES) expect(s.value).toMatch(/rem$/);
  });

  test("single spacing is not tighter than the manuscript default", () => {
    // The editor sets line-height 1.8. If "Single" meant 1.0 it would visibly
    // squash a document whose writer only wanted to confirm the current state.
    expect(parseFloat(LINE_SPACINGS[0].value)).toBeGreaterThanOrEqual(1.4);
  });

  test("spacings ascend", () => {
    const values = LINE_SPACINGS.map((s) => parseFloat(s.value));
    expect(values).toEqual([...values].sort((a, b) => a - b));
  });
});

describe("recase", () => {
  test("upper and lower are the obvious thing", () => {
    expect(recase("The Quick Fox", "upper")).toBe("THE QUICK FOX");
    expect(recase("The Quick Fox", "lower")).toBe("the quick fox");
  });

  test("title case keeps minor words lowercase", () => {
    expect(recase("the fall of the house of usher", "title")).toBe(
      "The Fall of the House of Usher",
    );
  });

  test("a minor word still capitalises when it opens or closes", () => {
    // Every style guide agrees on this, and it is the case a naive
    // capitalise-every-word implementation gets wrong in the other direction.
    expect(recase("the thing we walked in", "title")).toBe(
      "The Thing We Walked In",
    );
    expect(recase("a room of one's own", "title")).toBe("A Room of One's Own");
  });

  test("title case survives punctuation attached to a minor word", () => {
    expect(recase("notes on, and against, the novel", "title")).toBe(
      "Notes On, and Against, the Novel",
    );
  });

  test("original spacing is preserved rather than tidied", () => {
    // Selecting a line with a double space is not a request to reflow it.
    expect(recase("one  two", "title")).toBe("One  Two");
  });

  test("sentence case capitalises after terminal punctuation", () => {
    expect(recase("first one. second one! third one? fourth", "sentence")).toBe(
      "First one. Second one! Third one? fourth",
    );
  });

  test("empty and whitespace input do not throw", () => {
    expect(recase("", "title")).toBe("");
    expect(recase("   ", "title")).toBe("   ");
  });
});

