 * rather than a filled block. */
.twyne-editor .ProseMirror mark {
  background: linear-gradient(transparent 60%, rgba(212, 160, 23, 0.45) 60%);
  padding: 0;
  border-radius: 0;
}

/* A chosen colour arrives as an inline `background-color`, which cannot beat
 * the gradient above — `background-image` is a different longhand, so the
 * stroke would paint straight over the writer's colour and every highlight
 * would look mustard. Clearing the image lets the inline colour through. */
.twyne-editor .ProseMirror mark[data-color] {
  background-image: none;
}

/* Superscript and subscript, pinned so they cannot grow the line box.
 * Load-bearing for pagination: a raised character that makes its line taller
 * changes every page break below it. The same reasoning as .remote-cursor. */
.twyne-editor .ProseMirror sup,
.twyne-editor .ProseMirror sub {
  font-size: 0.72em;
  line-height: 0;
  position: relative;
  vertical-align: baseline;
}
